const DATE_PATTERN = /^(\d{4})-(\d{2})-(\d{2})$/;
const MONTH_STARTS = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334];
const MONTH_LENGTHS = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

function isLeapYear(year) {
  return year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
}

function daysBeforeYear(year) {
  const leapYears =
    Math.floor((year + 3) / 4) -
    Math.floor((year + 99) / 100) +
    Math.floor((year + 399) / 400);

  return year * 365 + leapYears;
}

const MIN_SERIAL = 0;
const MAX_SERIAL = daysBeforeYear(10000) - 1;

function parseDate(value) {
  if (typeof value !== "string" || value.length !== 10) {
    throw new RangeError("Invalid date");
  }

  const match = DATE_PATTERN.exec(value);
  if (match === null) {
    throw new RangeError("Invalid date");
  }

  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);

  if (month < 1 || month > 12) {
    throw new RangeError("Invalid date");
  }

  const maximumDay =
    MONTH_LENGTHS[month - 1] + (month === 2 && isLeapYear(year) ? 1 : 0);

  if (day < 1 || day > maximumDay) {
    throw new RangeError("Invalid date");
  }

  return (
    daysBeforeYear(year) +
    MONTH_STARTS[month - 1] +
    (month > 2 && isLeapYear(year) ? 1 : 0) +
    day -
    1
  );
}

function formatSerial(serial) {
  if (
    !Number.isInteger(serial) ||
    serial < MIN_SERIAL ||
    serial > MAX_SERIAL
  ) {
    throw new RangeError("Resulting date is outside YYYY-MM-DD range");
  }

  let lowerYear = 0;
  let upperYear = 10000;

  while (lowerYear + 1 < upperYear) {
    const middleYear = Math.floor((lowerYear + upperYear) / 2);

    if (daysBeforeYear(middleYear) <= serial) {
      lowerYear = middleYear;
    } else {
      upperYear = middleYear;
    }
  }

  const year = lowerYear;
  const monthLengths = MONTH_LENGTHS.slice();

  if (isLeapYear(year)) {
    monthLengths[1] = 29;
  }

  let dayOfYear = serial - daysBeforeYear(year);
  let monthIndex = 0;

  while (dayOfYear >= monthLengths[monthIndex]) {
    dayOfYear -= monthLengths[monthIndex];
    monthIndex += 1;
  }

  const month = monthIndex + 1;
  const day = dayOfYear + 1;

  return `${String(year).padStart(4, "0")}-${String(month).padStart(
    2,
    "0",
  )}-${String(day).padStart(2, "0")}`;
}

// Monday is 0 and Sunday is 6. In the proleptic Gregorian calendar,
// 0000-01-01 is a Saturday.
function weekdayOf(serial) {
  return (serial + 5) % 7;
}

function isWeekday(serial) {
  return weekdayOf(serial) < 5;
}

function nextWeekday(serial) {
  let next = serial + 1;
  const weekday = weekdayOf(next);

  if (weekday === 5) {
    next += 2;
  } else if (weekday === 6) {
    next += 1;
  }

  return next;
}

function buildHolidayCalendar(holidays) {
  if (!Array.isArray(holidays)) {
    throw new RangeError("holidays must be an array of valid dates");
  }

  const observed = new Set();
  const successors = new Map();
  const weekendHolidays = [];

  function firstFreeWeekday(initial) {
    let current = initial;
    const path = [];

    while (successors.has(current)) {
      path.push(current);
      current = successors.get(current);
    }

    for (const occupied of path) {
      successors.set(occupied, current);
    }

    return current;
  }

  function occupy(day) {
    if (observed.has(day)) {
      return;
    }

    const successor = firstFreeWeekday(nextWeekday(day));
    observed.add(day);
    successors.set(day, successor);
  }

  for (let index = 0; index < holidays.length; index += 1) {
    const holiday = parseDate(holidays[index]);

    if (isWeekday(holiday)) {
      occupy(holiday);
    } else {
      weekendHolidays.push(holiday);
    }
  }

  weekendHolidays.sort((a, b) => a - b);

  for (const holiday of weekendHolidays) {
    const nextMonday = holiday + (7 - weekdayOf(holiday));
    occupy(firstFreeWeekday(nextMonday));
  }

  return {
    observed,
    observedSorted: [...observed].sort((a, b) => a - b),
  };
}

function upperBound(sortedValues, target) {
  let lower = 0;
  let upper = sortedValues.length;

  while (lower < upper) {
    const middle = Math.floor((lower + upper) / 2);

    if (sortedValues[middle] <= target) {
      lower = middle + 1;
    } else {
      upper = middle;
    }
  }

  return lower;
}

function weekdaysThrough(serial) {
  if (serial < MIN_SERIAL) {
    return 0;
  }

  const numberOfDays = serial + 1;
  const completeWeeks = Math.floor(numberOfDays / 7);
  const remainingDays = numberOfDays % 7;

  return completeWeeks * 5 + Math.max(0, remainingDays - 2);
}

function businessDayRank(serial, observedSorted) {
  if (serial < MIN_SERIAL) {
    return 0;
  }

  return weekdaysThrough(serial) - upperBound(observedSorted, serial);
}

function serialForBusinessDayRank(target, observedSorted) {
  let lower = MIN_SERIAL;
  let upper = MAX_SERIAL;

  while (lower < upper) {
    const middle = Math.floor((lower + upper) / 2);

    if (businessDayRank(middle, observedSorted) >= target) {
      upper = middle;
    } else {
      lower = middle + 1;
    }
  }

  return lower;
}

function isBusinessSerial(serial, calendar) {
  return isWeekday(serial) && !calendar.observed.has(serial);
}

export function isBusinessDay(date, holidays = []) {
  const serial = parseDate(date);
  const calendar = buildHolidayCalendar(holidays);

  return isBusinessSerial(serial, calendar);
}

export function addBusinessDays(date, n, holidays = []) {
  const serial = parseDate(date);

  if (!Number.isInteger(n)) {
    throw new RangeError("n must be an integer");
  }

  const calendar = buildHolidayCalendar(holidays);
  const { observedSorted } = calendar;
  const totalBusinessDays = businessDayRank(MAX_SERIAL, observedSorted);

  if (n === 0) {
    if (isBusinessSerial(serial, calendar)) {
      return formatSerial(serial);
    }

    const currentRank = businessDayRank(serial, observedSorted);

    if (currentRank >= totalBusinessDays) {
      throw new RangeError("Resulting date is outside YYYY-MM-DD range");
    }

    return formatSerial(
      serialForBusinessDayRank(currentRank + 1, observedSorted),
    );
  }

  if (n > 0) {
    const currentRank = businessDayRank(serial, observedSorted);
    const availableBusinessDays = totalBusinessDays - currentRank;

    if (n > availableBusinessDays) {
      throw new RangeError("Resulting date is outside YYYY-MM-DD range");
    }

    return formatSerial(
      serialForBusinessDayRank(currentRank + n, observedSorted),
    );
  }

  const rankBeforeStart = businessDayRank(serial - 1, observedSorted);
  const amount = -n;

  if (amount > rankBeforeStart) {
    throw new RangeError("Resulting date is outside YYYY-MM-DD range");
  }

  const targetRank = rankBeforeStart - amount + 1;
  return formatSerial(serialForBusinessDayRank(targetRank, observedSorted));
}

export function businessDaysBetween(start, end, holidays = []) {
  const startSerial = parseDate(start);
  const endSerial = parseDate(end);
  const calendar = buildHolidayCalendar(holidays);

  const result =
    businessDayRank(endSerial, calendar.observedSorted) -
    businessDayRank(startSerial, calendar.observedSorted);

  return result === 0 ? 0 : result;
}
